// A thin cross-package facade. It publishes one name, and the value under
// that name is another package's function.
//
// Three separate wrong answers are available to an analyzer here, and all
// three read as "resolved" rather than as an error:
//
//  1. this file's OWN `dangerousOp` below -- a private helper the package
//     never publishes, present only because the export happens to be
//     spelled the same way (RWF-011);
//  2. the TOP-LEVEL node_modules/vt2-vuln-lib -- same name, same version,
//     same export name as the one this require really reaches, and the one
//     any resolution by package metadata rather than by path would find;
//  3. the facade package itself -- the export is physically declared here,
//     so attributing the target to vt2-facade-lib is superficially
//     defensible and completely wrong.
//
// Node's answer is none of those: `require("vt2-vuln-lib")` from THIS file
// resolves to this package's own nested install, because a nested
// node_modules is consulted before its parents.
function dangerousOp(input) {
  return "facade-local-helper:" + input;
}

exports.localHelper = dangerousOp;
exports.dangerousOp = require("vt2-vuln-lib").dangerousOp;
